import {contentIssues,renderBody,mountInlineLabs,normalizeBody} from './course-content.js?v=20261125-courses40';
import {topicLabs} from './topic-labs.js?v=20261125-courses40';
import {api,platform} from './platform.js?v=20261125-courses40';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=t=>t?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(t)):'尚无记录';
const labels={active:'已开通',pending:'待审核',blocked:'已暂停',revoked:'已撤销'};
const actions={activate_admin:'开通管理员',student_created:'创建学员',profile_updated:'修改人员权限',device_registered:'登记浏览器',device_updated:'修改设备授权',course_saved:'保存课程版本'};
let data,view='people',editing=null;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500);}
async function refresh(){data=await api('admin_dashboard');render();}
const person=id=>data.profiles.find(p=>p.id===id);
const name=id=>person(id)?.display_name||'学习者';
const pill=(status)=>`<span class="admin-status ${status}">${labels[status]||esc(status)}</span>`;
function render(){
  $('#app').innerHTML=`<header class="admin-header"><a class="admin-brand" href="./"><img src="./favicon.svg" alt=""><span>戊戌<span>.</span><small>管理后台</small></span></a><nav><a href="./">返回学习</a><span>${esc(platform.profile.display_name)}</span><button class="button secondary compact" data-admin="logout">退出</button></nav></header><main class="admin-main"><div class="page-eyebrow">YOUR LEARNING SPACE<span>人员、学习与课程管理</span></div><div class="page-heading"><div><h1>让学习，有序发生。</h1><p>账号权限、浏览器授权与课程进度，都在这里。</p></div><button class="button secondary compact" data-admin="refresh">刷新数据</button></div><div class="admin-stats"><div><b>${data.profiles.filter(p=>p.role==='student').length}</b><span>学员账号</span></div><div><b>${data.devices.filter(d=>d.status==='pending').length}</b><span>待审核浏览器</span></div><div><b>${data.courses.filter(c=>c.published).length}</b><span>已发布课程</span></div><div><b>${data.courses.filter(c=>!c.published).length}</b><span>课程草稿</span></div></div><nav class="filter-tabs admin-tabs">${[['people','人员与设备'],['progress','学习进度'],['courses','课程管理'],['audit','操作记录']].map(([v,label])=>`<button data-view="${v}" class="${view===v?'active':''}">${label}</button>`).join('')}</nav><div id="admin-view">${view==='people'?people():view==='progress'?progress():view==='courses'?courseManager():audit()}</div></main>`;
}
function people(){return `<section class="white-card admin-section"><div class="section-heading"><div><h2>开通学员账号</h2><p class="muted">账号创建后，首次登录的新浏览器仍需在下方批准。</p></div></div><form id="student-form" class="admin-create-form"><label class="input-field"><span>姓名或称呼</span><input name="display_name" required maxlength="80" autocomplete="off"></label><label class="input-field"><span>登录邮箱</span><input name="email" type="email" required autocomplete="off"></label><label class="input-field"><span>初始密码（至少 12 字符）</span><input name="password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label><label class="input-field"><span>浏览器数量上限</span><input name="max_devices" type="number" min="1" max="10" value="2" required></label><button class="button primary" type="submit">创建学员</button><p class="auth-error" role="alert"></p></form></section><section class="white-card admin-section"><div class="section-heading"><h2>人员权限</h2><span class="muted">暂停账号会阻止后续受保护请求。</span></div><div class="table-scroll"><table><thead><tr><th>人员</th><th>角色</th><th>账号状态</th><th>浏览器上限</th><th>最近访问</th><th></th></tr></thead><tbody>${data.profiles.map(p=>`<tr data-person="${p.id}"><td><b>${esc(p.display_name)}</b><small>${esc(p.email)}</small></td><td>${p.role==='admin'?'管理员':'学员'}</td><td><select name="status" aria-label="${esc(p.display_name)}的账号状态" ${p.id===platform.profile.id?'disabled':''}>${[['active','已开通'],['pending','待审核'],['blocked','已暂停']].map(([v,l])=>`<option value="${v}" ${p.status===v?'selected':''}>${l}</option>`).join('')}</select></td><td><input class="admin-number" name="max_devices" aria-label="${esc(p.display_name)}的设备上限" type="number" min="1" max="10" value="${p.max_devices}"></td><td>${when(p.last_seen_at)}</td><td><button class="button secondary compact" data-admin="save-person" data-id="${p.id}">保存设置</button></td></tr>`).join('')}</tbody></table></div></section><section class="white-card admin-section"><div class="section-heading"><div><h2>浏览器设备</h2><p class="muted">按浏览器授权管理。清除浏览器数据、换浏览器或设备后，可能需要重新批准。</p></div></div><div class="table-scroll"><table><thead><tr><th>人员与浏览器</th><th>状态</th><th>首次登记</th><th>最近访问</th><th>授权管理</th></tr></thead><tbody>${data.devices.map(d=>`<tr><td><b>${esc(name(d.user_id))}</b><small>${esc(d.label)} · ${d.id.slice(0,8)}${d.id===platform.device.id?' · 当前浏览器':''}</small></td><td>${pill(d.status)}</td><td>${when(d.created_at)}</td><td>${when(d.last_seen_at)}</td><td><div class="button-row">${d.status!=='active'?`<button class="button primary compact" data-admin="device" data-id="${d.id}" data-status="active">批准</button>`:''}${d.status!=='revoked'&&d.id!==platform.device.id?`<button class="button secondary compact" data-admin="device" data-id="${d.id}" data-status="revoked">撤销授权</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></section>`;}
function progress(){return `<div class="section-heading"><div><h2>按学员检查学习情况</h2><p class="muted">阅读进度来自学员自己的理解标记，练习成绩由服务器核对。这里不展示学习笔记正文。</p></div></div>${data.profiles.filter(p=>p.role==='student').map(p=>{const learning=data.learning.find(l=>l.user_id===p.id),state=learning?.courses||{};return `<section class="white-card admin-section"><div class="section-heading"><div><h2>${esc(p.display_name)}</h2><p class="muted">${esc(p.email)} · 最近保存 ${when(learning?.updated_at)}</p></div>${pill(p.status)}</div><div class="table-scroll"><table><thead><tr><th>课程</th><th>阅读标记</th><th>最佳答对</th><th>练习次数</th><th>进度</th></tr></thead><tbody>${data.courses.filter(c=>c.published).map(c=>{const r=state[c.id]||{},valid=r.courseRevision===c.revision,read=c.payload.sections.filter(s=>r.read?.includes(s.id)).length,best=valid?r.best||0:0,pct=Math.round((read+best)/(c.payload.sections.length+c.payload.quiz.length)*100);return `<tr><td>${esc(c.title)}${!valid&&r.attempts?' <span class="pill">课程已更新，待复习</span>':''}</td><td>${read}/${c.payload.sections.length}</td><td>${best}/${c.payload.quiz.length}</td><td>${valid?r.attempts||0:0}</td><td>${pct}%</td></tr>`;}).join('')}</tbody></table></div></section>`;}).join('')||'<div class="empty-state">创建学员账号后，可以在这里查看学习进度。</div>'}`;}
function audit(){return `<div class="white-card table-scroll"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>对象</th><th>详情</th></tr></thead><tbody>${data.audit.map(a=>`<tr><td>${when(a.created_at)}</td><td>${esc(name(a.actor))}</td><td>${actions[a.action]||esc(a.action)}</td><td>${esc(a.target?.slice(0,16)||'')}</td><td>${esc(a.detail?.status?labels[a.detail.status]:a.detail?.revision?'第 '+a.detail.revision+' 版':'')}</td></tr>`).join('')}</tbody></table></div><p class="admin-note">显示最近 100 条管理操作和浏览器登记记录。</p>`;}
const emptyCourse=()=>({id:Math.max(0,...data.courses.map(c=>c.id))+1,title:'',subtitle:'',category:'金融知识',description:'',minutes:40,keywords:[],calculator:'compound',sections:Array.from({length:4},(_,i)=>({id:'concept-'+(i+1),title:'',body:'',formula:'',meaning:''})),cases:[{title:'',body:'',takeaway:''}],quiz:Array.from({length:3},(_,i)=>({id:'q'+(i+1),q:'',options:['','',''],correct:0,explain:'',section:'concept-1'}))});
const paragraphs=body=>String(body||'');
const html=text=>/<\/?(?:p|ul|ol|li|strong|em|table|thead|tbody|tr|th|td|br)(?:>|\s)/i.test(text)?text:text.split(/\n\s*\n/).filter(Boolean).map(p=>'<p>'+esc(p).replace(/\n/g,'<br>')+'</p>').join('');
const input=(label,name,value,extra='')=>`<label class="input-field"><span>${label}</span><input name="${name}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value,rows=4,required=true)=>`<label class="input-field full"><span>${label}</span><textarea name="${name}" rows="${rows}" ${required?'required':''}>${esc(value)}</textarea></label>`;
function courseManager(){return `<div class="section-heading"><div><h2>课程与复习内容</h2><p class="muted">新增课程会自动加入目录、搜索、复习卡片与学习进度。</p></div><button class="button primary compact" data-admin="new-course">新增课程</button></div><div class="course-admin-list">${data.courses.map(c=>`<button class="course-admin-card white-card" data-admin="edit-course" data-id="${c.id}"><span class="eyebrow">第 ${c.id} 讲 · 版本 ${c.revision}</span><b>${esc(c.title)}</b><span>${c.published?'已发布':'草稿'} · ${c.payload.sections.length} 个单元 · ${c.payload.quiz.length} 道测试</span><small>编辑课程</small></button>`).join('')}</div>${editing?editor():''}`;}
function editor(){const {course:c,revision,published}=editing;return `<section class="white-card course-editor" id="course-editor"><div class="section-heading"><div><h2>${revision?'编辑课程':'新增课程'} · 第 ${c.id} 讲</h2><p class="muted">单元与题目编号用于关联旧进度；修订时请尽量保留已有编号。</p></div><button class="button secondary compact" data-admin="close-editor">收起编辑</button></div><form id="course-form" method="post" class="editor-form"><div class="field-grid">${input('课程标题','title',c.title,'required maxlength="120"')}${input('副标题','subtitle',c.subtitle,'required maxlength="160"')}${input('分类','category',c.category,'required maxlength="80"')}${input('预计学习时长（分钟）','minutes',c.minutes,'type="number" min="1" max="1440" required')}${input('关键词（用逗号分隔）','keywords',c.keywords.join('，'),'maxlength="400"')}<label class="input-field"><span>配套计算器</span><select name="calculator">${[['purchasing','购买力'],['credit','等额本息'],['compound','单利与复利'],['fx','换汇预算'],['inflation','实际收益'],['balance','资产负债'],['liquidity','现金缓冲'],['portfolio','股债组合'],['valuation','股票估值'],['bond','债券定价与股债组合'],['institution','金融机构经营与风险资本'],['acquisition','并购估值与协同效应'],...Object.entries(topicLabs).map(([k,v])=>[k,v.title])].map(([v,l])=>`<option value="${v}" ${c.calculator===v?'selected':''}>${l}</option>`).join('')}</select></label>${area('课程简介','description',c.description,3)}</div><div class="editor-title"><h3>核心概念</h3><button type="button" class="button secondary compact" data-admin="add-unit" data-kind="sections">添加知识单元</button></div><div id="sections-editor">${c.sections.map((s,i)=>`<fieldset class="editor-unit" data-unit="sections"><legend>知识单元 ${i+1}</legend><div class="field-grid">${input('稳定编号（英文或数字）','id',s.id,'pattern="[a-z][a-z0-9-]*" required')}${input('单元标题','title',s.title,'required')}${area('通俗讲解（保留HTML结构；纯文本可空行分段）','body',paragraphs(s.body),6)}${area('计算公式（可选）','formula',s.formula,2,false)}${area('公式口径与变量说明（可选）','meaning',s.meaning,2,false)}</div>${c.sections.length>4?`<button type="button" class="text-button" data-admin="remove-unit" data-kind="sections" data-index="${i}">移除此单元</button>`:''}</fieldset>`).join('')}</div><div class="editor-title"><h3>生活案例</h3><button type="button" class="button secondary compact" data-admin="add-unit" data-kind="cases">添加案例</button></div><div id="cases-editor">${c.cases.map((k,i)=>`<fieldset class="editor-unit" data-unit="cases"><legend>生活案例 ${i+1}</legend>${input('案例标题','title',k.title,'required')}${area('案例正文（保留HTML结构）','body',paragraphs(k.body),6)}${area('带走的判断','takeaway',k.takeaway,2)}${c.cases.length>1?`<button type="button" class="text-button" data-admin="remove-unit" data-kind="cases" data-index="${i}">移除此案例</button>`:''}</fieldset>`).join('')}</div><div class="editor-title"><h3>测试题与解析</h3><button type="button" class="button secondary compact" data-admin="add-unit" data-kind="quiz">添加测试题</button></div><div id="quiz-editor">${c.quiz.map((q,i)=>`<fieldset class="editor-unit" data-unit="quiz"><legend>测试题 ${i+1}</legend><div class="field-grid">${input('稳定题目编号','id',q.id,'pattern="[a-z][a-z0-9-]*" required')}${input('关联的单元编号','section',q.section,'required')}${area('题目','q',q.q,2)}${[0,1,2,3].map(j=>input('选项 '+['A','B','C','D'][j],'option'+j,q.options[j]||'',j<2?'required':'')).join('')}<label class="input-field"><span>正确答案</span><select name="correct">${[0,1,2,3].map(j=>`<option value="${j}" ${q.correct===j?'selected':''}>${['A','B','C','D'][j]}</option>`).join('')}</select></label>${area('答案解析','explain',q.explain,3)}</div>${c.quiz.length>3?`<button type="button" class="text-button" data-admin="remove-unit" data-kind="quiz" data-index="${i}">移除此题</button>`:''}</fieldset>`).join('')}</div><div class="editor-save"><label><input name="published" type="checkbox" ${published?'checked':''}> 发布后供学员学习</label><p>保存会建立新版本；已修改的课程测试需要重新练习。</p><p class="auth-error" role="alert"></p><button class="button secondary" type="button" data-admin="preview-course">预览课程并检查排版</button><button class="button primary" type="submit">保存课程版本</button></div></form></section>`;}
function collect(){const f=$('#course-form'),c=structuredClone(editing.course);const top=f.querySelector(':scope > .field-grid');for(const name of ['title','subtitle','category','description','calculator'])c[name]=top.querySelector('[name="'+name+'"]').value.trim();c.minutes=Number(f.minutes.value);c.keywords=f.keywords.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);for(const kind of ['sections','cases','quiz'])c[kind]=$$(`[data-unit="${kind}"]`,f).map(unit=>{const get=n=>unit.querySelector(`[name="${n}"]`)?.value.trim()||'';return kind==='sections'?{id:get('id'),title:get('title'),body:normalizeBody(html(get('body')),document),formula:get('formula'),meaning:get('meaning')}:kind==='cases'?{title:get('title'),body:normalizeBody(html(get('body')),document),takeaway:get('takeaway')}:{id:get('id'),q:get('q'),options:[get('option0'),get('option1'),get('option2'),get('option3')].filter(Boolean),correct:Number(get('correct')),explain:get('explain'),section:get('section')};});editing.course=c;editing.published=f.published.checked;}
document.addEventListener('click',async e=>{
  const tab=e.target.closest('[data-view]');if(tab){if(editing&&$('#course-form'))collect();view=tab.dataset.view;render();return;}
  const b=e.target.closest('[data-admin]');if(!b)return;const a=b.dataset.admin;
  try{
    if(a==='logout'){await platform.logout();return;}
    if(a==='refresh'){await refresh();toast('数据已刷新。');}
    if(a==='save-person'){const row=b.closest('tr'),limit=row.querySelector('[name=max_devices]');if(!limit.checkValidity()){limit.reportValidity();return;}b.disabled=true;await api('profile_update',{user_id:b.dataset.id,status:row.querySelector('[name=status]').value,max_devices:Number(limit.value)});await refresh();toast('人员设置已保存。');}
    if(a==='device'){b.disabled=true;await api('device_update',{device_id:b.dataset.id,status:b.dataset.status});await refresh();toast('设备授权已更新。');}
    if(a==='new-course'){editing={course:emptyCourse(),revision:0,published:false};render();$('#course-editor').scrollIntoView({behavior:'smooth',block:'start'});}
    if(a==='edit-course'){const row=data.courses.find(c=>c.id===Number(b.dataset.id));editing={course:structuredClone(row.payload),revision:row.revision,published:row.published};render();$('#course-editor').scrollIntoView({behavior:'smooth',block:'start'});}
    if(a==='preview-course'){collect();const c=editing.course,issues=contentIssues(c),dialog=document.createElement('dialog');dialog.className='course-preview';dialog.innerHTML='<form method="dialog"><button class="button secondary">关闭预览</button></form><h2>'+esc(c.title)+'</h2><p>'+esc(issues.length?'检查发现：'+issues.join('；'):'结构与公式检查通过。请继续核对案例数字和阅读效果。')+'</p>'+[...c.sections,...c.cases].map(s=>'<article><h3>'+esc(s.title)+'</h3><div class="prose">'+renderBody(s.body)+'</div></article>').join('');document.body.append(dialog);mountInlineLabs(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());}
    if(a==='close-editor'){editing=null;render();}
    if(a==='add-unit'||a==='remove-unit'){collect();const kind=b.dataset.kind;if(a==='remove-unit')editing.course[kind].splice(Number(b.dataset.index),1);else{const n=editing.course[kind].length+1;editing.course[kind].push(kind==='sections'?{id:'concept-'+crypto.randomUUID().slice(0,8),title:'',body:'',formula:'',meaning:''}:kind==='cases'?{title:'',body:'',takeaway:''}:{id:'q'+crypto.randomUUID().slice(0,8),q:'',options:['','',''],correct:0,explain:'',section:editing.course.sections[0].id});}const scroll=window.scrollY;render();window.scrollTo(0,scroll);}
  }catch(error){toast(error.message);b.disabled=false;}
});
document.addEventListener('submit',async e=>{
  if(e.target.getAttribute('id')==='student-form'){e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('create_student',{email:f.email.value,display_name:f.display_name.value,password:f.password.value,max_devices:Number(f.max_devices.value)});f.password.value='';await refresh();toast('账号已创建。学员首次登录后，请批准其浏览器。');}catch(error){f.querySelector('.auth-error').textContent=error.message;b.disabled=false;}}
  if(e.target.getAttribute('id')==='course-form'){e.preventDefault();const f=e.target,b=f.querySelector('button[type=submit]');collect();b.disabled=true;try{const issues=contentIssues(editing.course);if(issues.length)throw Error('发布检查未通过：'+issues.slice(0,3).join('；'));await api('course_save',{course:editing.course,published:editing.published,expected_revision:editing.revision});editing=null;await refresh();toast('课程版本已保存。学员刷新页面后即可看到更新。');}catch(error){f.querySelector('.auth-error').textContent=error.message;b.disabled=false;}}
});
await refresh();
